const contacts = $input.all();
const results = [];

// Nurture content berdasarkan step
const nurtureSeries = [
  {
    step: 0,
    subject: '5 Tips to Improve Your {{industry}} Strategy',
    template: 'd-nurture-tips',
    content_type: 'educational'
  },
  {
    step: 1,
    subject: 'Case Study: How {{similar_company}} Achieved 3x Growth',
    template: 'd-nurture-case-study',
    content_type: 'social_proof'
  },
  {
    step: 2,
    subject: '{{first_name}}, here\'s a free resource for you',
    template: 'd-nurture-resource',
    content_type: 'value_add'
  },
  {
    step: 3,
    subject: 'Ready to take the next step, {{first_name}}?',
    template: 'd-nurture-cta',
    content_type: 'soft_cta'
  },
  {
    step: 4,
    subject: 'Let\'s schedule a quick chat',
    template: 'd-nurture-meeting',
    content_type: 'hard_cta'
  }
];

for (const item of contacts) {
  const contact = item.json;
  const step = Math.min(contact.nurture_step || 0, nurtureSeries.length - 1);
  const content = nurtureSeries[step];

  // Personalisasi subject
  let subject = content.subject
    .replace('{{first_name}}', contact.first_name || 'there')
    .replace('{{industry}}', contact.custom_fields?.industry || 'Business')
    .replace('{{similar_company}}', 'Industry Leaders');

  results.push({
    json: {
      ...contact,
      nurture_step: step,
      email_subject: subject,
      template_id: content.template,
      content_type: content.content_type
    }
  });
}

return results;

